-- =====================================================================
-- manual: expression indexes. Trigram (pg_trgm) search indexes have no SQLite equivalent and were dropped.
CREATE INDEX "idx_users_full_name" ON "users" (lower(full_name));
CREATE INDEX "idx_boards_workspace_open" ON "boards" (workspace_id, lower(name)) WHERE closed_at IS NULL;
-- A link between two cards is unique regardless of direction.
CREATE UNIQUE INDEX "uq_card_links_pair" ON "card_links" (min(source_card_id, target_card_id), max(source_card_id, target_card_id));

-- manual: one pending invite per (workspace, board or none, email); NULL board_id must collide too.
-- SQLite has no NULLS NOT DISTINCT; an expression index (which Prisma does not diff) does it instead.
CREATE UNIQUE INDEX "uq_invites_pending_target_nulls" ON "invites" (workspace_id, ifnull(board_id, ''), email) WHERE status = 'pending';
